(function(){
  function getLang(){
    return localStorage.getItem('zafiraLang')||'en';
  }
  function applyLang(lang){
    localStorage.setItem('zafiraLang',lang);

    /* Textos simples */
    document.querySelectorAll('[data-'+lang+']').forEach(function(el){
      el.textContent=el.getAttribute('data-'+lang);
    });

    /* Textos HTML */
    document.querySelectorAll('[data-'+lang+'-html]').forEach(function(el){
      el.innerHTML=el.getAttribute('data-'+lang+'-html');
    });

    /* Placeholders */
    document.querySelectorAll('[data-'+lang+'-ph]').forEach(function(el){
      el.placeholder=el.getAttribute('data-'+lang+'-ph');
    });

    /* Botones de idioma */
    document.querySelectorAll('.lang-btn').forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-lang')===lang);
    });
  }

  window.zafiraSetLang=function(lang){applyLang(lang);}
  window.zafiraGetLang=function(){return getLang();}

  /* Aplicar al cargar */
  document.addEventListener('DOMContentLoaded',function(){
    applyLang(getLang());
  });
})();
