  <script>
    (function(){
      const canvas = document.getElementById('heroCanvas');
      if(!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      let width, height;
      let particles = [];
      let mouse = { x: window.innerWidth/2, y: window.innerHeight/2, targetX: window.innerWidth/2, targetY: window.innerHeight/2 };

      function init() {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
        particles = [];
        const count = window.innerWidth < 768 ? 50 : 120;
        for(let i=0; i<count; i++) {
          particles.push({
            x: Math.random() * width,
            y: Math.random() * height,
            r: Math.random() * 1.5 + 0.3,
            dx: (Math.random() - 0.5) * 0.3,
            dy: (Math.random() - 0.5) * 0.3,
            baseAlpha: Math.random() * 0.5 + 0.1,
            z: Math.random() * 0.6 + 0.2 // Depth for parallax
          });
        }
      }

      window.addEventListener('resize', init);
      
      const heroSec = document.getElementById('hero');
      heroSec.addEventListener('mousemove', (e) => {
        const rect = heroSec.getBoundingClientRect();
        mouse.targetX = e.clientX - rect.left;
        mouse.targetY = e.clientY - rect.top;
      });
      heroSec.addEventListener('mouseleave', () => {
        mouse.targetX = width/2;
        mouse.targetY = height/2;
      });

      function animate() {
        requestAnimationFrame(animate);
        ctx.clearRect(0, 0, width, height);

        // Extremely soft easing for luxury feel
        mouse.x += (mouse.targetX - mouse.x) * 0.03;
        mouse.y += (mouse.targetY - mouse.y) * 0.03;

        const centerX = width / 2;
        const centerY = height / 2;
        
        const shiftX = (mouse.x - centerX) * 0.06;
        const shiftY = (mouse.y - centerY) * 0.06;

        particles.forEach(p => {
          p.x += p.dx;
          p.y += p.dy;

          if(p.x < -20) p.x = width + 20;
          if(p.x > width + 20) p.x = -20;
          if(p.y < -20) p.y = height + 20;
          if(p.y > height + 20) p.y = -20;

          // Inverse parallax: closer particles move more
          const px = p.x - shiftX * p.z;
          const py = p.y - shiftY * p.z;

          ctx.beginPath();
          ctx.arc(px, py, p.r, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(201, 168, 76, ${p.baseAlpha})`;
          ctx.fill();
        });
      }
      
      init();
      animate();
    })();
  </script>
